{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.98,
  "summary": [
    "Early 2026 data show 606 Mediterranean deaths/missing by late February, the deadliest start to a year on record for IOM data.",
    "If the current pace persists into March, reaching 900 deaths before April is plausible, though not guaranteed.",
    "Weather extremes, SAR capacity constraints, increased departures, and potential undercounts all tilt the risk toward 900, with uncertainty from reporting lags.",
    "Calibrated posterior reflects high likelihood given divergent evidence but acknowledges correlation and data-revision risks."
  ],
  "confidence": "high",
  "narrative": "Anchoring on the central Mediterranean toll in early 2026, the observed pace strongly points toward a 900-death toll by the end of March if momentum continues. Additional factors such as weather, rescue capacity, and ongoing departures reinforce the upper-end risk, though reporting lags and potential policy changes inject uncertainty. The calibrated posterior probability is 0.95 with a plausible range around 0.90–0.98.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class is IOM Missing Migrants Project Central Mediterranean calendar-year tolls; use early-2026 counts to anchor an annual pace. The 0.65 anchor reflects a plausible starting probability before updating with the strong early-2026 data."
    },
    "factor_updates": [
      {
        "factor": "Current pace of Mediterranean deaths in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "As of Feb 24, 2026, at least 606 deaths/missing; continuing at this pace would require ~294 additional deaths in March to reach 900, making the target plausible."
      },
      {
        "factor": "Weather extremes and storms affecting crossing risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Storm activity and rough seas increase crossing risk and likelihood of shipwrecks, sustaining high mortality risk into March."
      },
      {
        "factor": "Policy SAR capacity and funding constraints",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Constraints on rescue operations and funding can reduce lifesaving responses, elevating fatalities if rescues are delayed or limited."
      },
      {
        "factor": "Surge in departures from Libya/Tunisia and smugglers’ activity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher departure pressure and ongoing smuggling activity raise exposure to dangerous crossings, aligning with higher early-2026 mortality."
      },
      {
        "factor": "Reporting gaps and undercount risk",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "IOM data can undercount or revise upward; late confirmations could lift the March toll beyond initial counts."
      }
    ],
    "synthesis_rationale": "Starting from a 0.65 anchor, strong upticks from multiple independent indicators (pace through Feb, weather, SAR capacity, and departures) collectively push the posterior toward 0.95. Correlations among factors (e.g., pace and weather) temper the pure additive effect, hence the calibrated, slightly conservative range (0.90–0.98) to reflect uncertainty and potential data revisions."
  }
}

